import {ac8Asset,ac8Links} from './ac8-content.js';
import {contourPaths} from './ac8-ambient-state.js';
const icon=(id,cls='ic')=>`<svg class="${cls}" aria-hidden="true"><use href="${id.startsWith('#')?id:'./assets/flow/current-icons.svg#'+id}"></use></svg>`;
// Heading tape across the top of the HUD: ticks every 5°, labels every 30°. Decorative only.
const tape=()=>{let d='',labels='';for(let i=0;i<=72;i++){const x=i*20;d+=`M${x} ${i%6===0?0:8}V20`;if(i%6===0)labels+=`<text x="${x}" y="34">${String((i*5)%360).padStart(3,'0')}</text>`;}return `<svg class="ac8-tape" viewBox="0 0 1440 40" preserveAspectRatio="xMidYMin slice" aria-hidden="true"><path d="${d}"/>${labels}</svg>`;};
export function ac8Exhibit(){return `<section class="game-exhibit ac8-exhibit" id="ace-combat-8" aria-labelledby="ac8-title" data-ac8-scene data-theme="dark">
 <div class="ac8-stage" data-ac8-stage>
  <div class="ac8-map-window" aria-hidden="true"><img class="ac8-map" src="${ac8Asset}battlefield.svg" width="1200" height="800" alt=""><div class="ac8-map-wash"></div><svg class="ac8-radar" viewBox="0 0 1200 800" preserveAspectRatio="xMidYMid slice"><defs><radialGradient id="ac8-radar-light"><stop stop-color="#d5ed9c" stop-opacity=".22"/><stop offset="1" stop-color="#d5ed9c" stop-opacity="0"/></radialGradient></defs><g class="ac8-live-contours" data-ac8-contours>${contourPaths(0).map((d,i)=>`<path d="${d}" data-contour="${i}"/>`).join('')}</g><circle cx="680" cy="400" r="265" fill="none" stroke="currentColor" stroke-width="1"/><circle cx="680" cy="400" r="180" fill="none" stroke="currentColor" stroke-dasharray="3 12"/><path d="M680 135V665M415 400H945" stroke="currentColor" stroke-width=".6"/><path class="ac8-radar-sweep" d="M680 400L680 135A265 265 0 0 1 945 400Z" fill="url(#ac8-radar-light)"/><g class="ac8-vector-targets" fill="none" stroke="currentColor"><path d="M205 260l18-14 18 14-18 14Z M858 160l18-14 18 14-18 14Z M370 620l18-14 18 14-18 14Z"/><path d="M223 246L680 400 876 160M388 620L680 400" stroke-dasharray="4 9"/></g><g class="ac8-enemy-layer" data-ac8-enemy-layer></g><g class="ac8-target-ring"><circle cx="876" cy="160" r="28" fill="none" stroke="#ff6748"/><path d="M876 118V135M876 185V202M834 160H851M901 160H918" stroke="#ff6748"/></g></svg><div class="ac8-cloud ac8-cloud-a"></div><div class="ac8-cloud ac8-cloud-b"></div></div>
  <header class="ac8-hud-top"><span data-i18n="ac8.eyebrow">04 / 空战奇兵 · THEVE 航图</span><span>STRANGEREAL / JOKER FLIGHT</span><span class="ac8-hud-id">AC / 08</span>${tape()}</header>
  <div class="ac8-title-layer"><h2 id="ac8-title"><span class="ac8-line-mask"><span>ACE</span></span><span class="ac8-line-mask"><span>COMBAT<b>8</b></span></span></h2><span class="ac8-subtitle">WINGS OF THEVE / THE FLIGHT FILE</span><p data-i18n="ac8.intro">在云层切开的战场里，寻找自己的航线。飞行，不只是抵达，也是向上。</p></div>
  <div class="ac8-aircraft" data-ac8-aircraft><img src="${ac8Asset}f35c-cutout.png" width="3000" height="2328" alt="F‑35C Lightning II 真实俯视轮廓" data-i18n-alt="ac8.f35"></div>
  <svg class="ac8-effects" data-ac8-effects viewBox="0 0 1200 800" preserveAspectRatio="xMidYMid slice" aria-hidden="true"><defs><filter id="ac8-small-paper" x="-25%" y="-50%" width="150%" height="200%"><feMorphology in="SourceAlpha" operator="dilate" radius="1.2" result="edgeAlpha"/><feFlood flood-color="#fffefb"/><feComposite in2="edgeAlpha" operator="in"/><feMerge><feMergeNode/><feMergeNode in="SourceGraphic"/></feMerge></filter></defs><g class="ac8-flare-layer" data-ac8-flare-layer></g><g class="ac8-launch-layer" data-ac8-launch-layer></g></svg>
  <div class="ac8-ambient-hud" aria-hidden="true"><span>ART LOOP <b data-ac8-wave>01</b></span><span>HOSTILES <b data-ac8-enemy-count>03</b></span><span>FLARES <b data-ac8-flare-count>00</b></span></div>
  <div class="ac8-wing-label" aria-hidden="true"><span>F‑35C</span><small>LIGHTNING II / MULTIROLE</small><svg viewBox="0 0 150 40"><path d="M0 5H85L140 35" fill="none" stroke="currentColor"/><circle cx="140" cy="35" r="3" fill="currentColor"/></svg></div>
  <div class="ac8-tasha-wrap" data-ac8-sticker><svg class="ac8-tasha" viewBox="-26 -26 787 1509" role="img" aria-label="用户提供的塔莎造型照片，Adobe 非生成式抠图与白边贴纸" data-i18n-label="ac8.tashaAlt"><defs><filter id="ac8-paper-edge" x="-15%" y="-15%" width="130%" height="130%"><feMorphology in="SourceAlpha" operator="dilate" radius="18" result="expanded"/><feFlood flood-color="#fffefb" result="paper"/><feComposite in="paper" in2="expanded" operator="in" result="edge"/><feMerge><feMergeNode in="edge"/><feMergeNode in="SourceGraphic"/></feMerge></filter></defs><image href="${ac8Asset}tasha-cutout.png" width="735" height="1457" filter="url(#ac8-paper-edge)"/></svg><span class="ac8-tasha-stamp">TASHA<span>JOKER / 03</span></span><span class="ac8-tasha-note" data-i18n="ac8.stickerNote">TASHA / 用户提供造型照片</span></div>
  <i class="ac8-bracket ac8-bracket-tl" aria-hidden="true"></i><i class="ac8-bracket ac8-bracket-tr" aria-hidden="true"></i><i class="ac8-bracket ac8-bracket-bl" aria-hidden="true"></i><i class="ac8-bracket ac8-bracket-br" aria-hidden="true"></i>
  <div class="ac8-chart-foot"><span>THEVE / 04</span><span data-i18n="ac8.sceneNote">概念航图 / 艺术化轨迹</span><span>ENDURANCE / FCU</span></div>
 </div>
 <div class="ac8-cockpit">
  <div class="ac8-view-copy"><h3 data-ac8-view-title>穿过云层，世界才有轮廓。</h3><p data-ac8-view-copy>同一架 F‑35C，掠过被等高线切开的云海。</p><span class="ac8-launch-status" data-ac8-launch-status role="status" aria-live="polite"></span></div>
  <div class="ac8-flight-console"><div class="ac8-view-buttons" role="group" aria-label="切换航图视角" data-i18n-label="ac8.viewGroup">${['cloudsea','vectorwar','afterburn'].map((id,i)=>`<button type="button" data-ac8-view="${i}" aria-pressed="${i===0}"><small>0${i+1}</small><span data-i18n="ac8.view${i}">${['云海','战场','尾焰'][i]}</span></button>`).join('')}</div><button class="ac8-fire" type="button" data-ac8-fire aria-label="播放艺术化导弹发射轨迹" data-i18n-label="ac8.fireLabel">${icon('#gr-cross','ac8-fire-cross')}<span data-i18n="ac8.fire">发射一条轨迹</span>${icon('arrow-up-right','ic ac8-fire-go')}</button></div>
 </div>
 <section class="ac8-flight-log" aria-labelledby="ac8-log-title">
  <div class="ac8-log-heading"><div><span class="ac8-log-src" data-i18n="ac8.recordEyebrow">STEAM / 我的飞行记录</span><h3 id="ac8-log-title" data-i18n="ac8.recordTitle">把时间，留在天空里。</h3></div><div class="ac8-sync"><i></i><span data-ac8-status data-i18n="ac8.connecting">正在连接飞行记录</span></div></div>
  <div class="ac8-stats"><div class="ac8-gauge"><span data-i18n="ac8.total">累计游玩</span><strong data-ac8-total>—</strong><small>STEAM / TOTAL</small></div><div class="ac8-gauge"><span data-i18n="ac8.recent">近两周</span><strong data-ac8-recent>—</strong><small>STEAM / 2 WEEKS</small></div><div class="ac8-gauge"><span data-i18n="ac8.lastPlayed">最近启动</span><time data-ac8-last>—</time><small>STEAM / LAST PLAYED</small></div></div>
  <div class="ac8-data-footer"><div><span data-i18n="ac8.sourceTime">Steam 来源更新</span><time data-ac8-source>—</time></div><div><span data-ac8-collected-label data-i18n="ac8.syncTime">最近同步</span><time data-ac8-synced>—</time></div><button type="button" data-ac8-refresh><span data-i18n="ac8.refresh">刷新记录</span>${icon('#gr-refresh')}</button></div>
  <p class="ac8-log-note" data-i18n="ac8.recordNote">按 Steam 客户端实际写入同步；游玩时长通常在结束游戏后更新。电脑离线时保留最近记录。</p>
 </section>
 <footer class="ac8-colophon"><a href="${ac8Links.store}" target="_blank" rel="noopener noreferrer"><span data-i18n="ac8.store">进入 Steam 游戏页</span>${icon('arrow-up-right')}</a><a href="${ac8Links.official}" target="_blank" rel="noopener noreferrer"><span data-i18n="ac8.official">游戏官方档案</span>${icon('arrow-up-right')}</a><span class="ac8-colophon-id">04 / CHEFZC · THE OTHER SKY</span></footer><p class="ac8-credit"><span data-i18n="ac8.credit">个人非官方展位。F‑35C 参考：JSF / 美国国防部，经 Adobe 抠图。塔莎造型照片由用户提供，经 Adobe 抠图；航图与动效为原创展示。</span> <a href="${ac8Links.aircraft}" target="_blank" rel="noopener noreferrer">F‑35C SOURCE${icon('arrow-up-right')}</a></p>
</section>`;}
